const descriptionHtml =
  $json.job?.job_information?.description ?? '';

// Convert the HTML description into readable plain text
const descriptionText = descriptionHtml
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|li|div|h[1-6]|ul|ol)>/gi, '\n')
  .replace(/<li[^>]*>/gi, '- ')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\n[ \t]+/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const resolvedCompany =
  $json.company_identity?.recommendedCompanyName ?? '';

return {
  json: {
    // Preserve EVERYTHING we've accumulated so far
    ...$json,

    // Normalized fields used by downstream nodes
    title:
      $json.job_information?.title ??
      $json.v5_processed_job_data?.core_job_title ??
      '',

    company: resolvedCompany,

    applyUrl: $json.apply_url ?? '',

    requirementsSummary:
      $json.v5_processed_job_data?.requirements_summary ?? '',

    technicalTools:
      $json.v5_processed_job_data?.technical_tools ?? [],

    descriptionHtml,
    descriptionText,
  },
};

const sponsorEntityName = String(
  $json.sponsor_entity_mapping?.['Verified Sponsor Entity Name'] ?? ''
).trim();

if (!sponsorEntityName) {
  throw new Error('No verified sponsor entity available for sponsor search.');
}

return {
  json: {
    ...$json,
    sponsorSearchTerm: sponsorEntityName,
  },
};

const html = $input.first().json.data;

const match = html.match(
  /<script[^>]*id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/
);

if (!match) {
  throw new Error("__NEXT_DATA__ not found");
}

const nextData = JSON.parse(match[1]);

const jobs = nextData.props?.pageProps?.ssrHits;

if (!Array.isArray(jobs)) {
  throw new Error("Expected props.pageProps.ssrHits to be an array");
}

return jobs.map((job) => ({
  json: job,
}));

const jobRecord = $('Classify Job Sponsorship Language').item.json;
const companyIdentity = $json.output;

return {
  json: {
    ...jobRecord,
    company_identity: companyIdentity,
  },
};

const html = String($json.data ?? '');

// Recover the complete job record that entered the HTTP request
const job = $('Prepare Sponsor Search').item.json;

// Detect an explicit no-results response
const noResults =
  /returns\s+no\s+results/i.test(html);

// Extract the result table row
const rowRegex =
  /<tr>\s*<td>1<\/td>\s*<td>(.*?)<\/td>\s*<td[^>]*>\s*<a\s+href=['"]([^'"]+)['"][^>]*>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<\/tr>/is;

const match = html.match(rowRegex);

function clean(value) {
  return String(value ?? '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

let sponsorLookup = {
  searchTerm: job.sponsorSearchTerm ?? '',
  found: false,
  resultCount: 0,
  employerName: null,
  employerPath: null,
  visaRank: null,
  h1bDeniedOrWithdrawn: null,
  h1bTotalApplications: null,
  greenCardDeniedOrWithdrawn: null,
  greenCardTotalApplications: null,
};

if (!noResults && match) {
  const visaRank = clean(match[1]);
  const employerPath = clean(match[2]);
  const employerName = clean(match[3]);

  const h1b = clean(match[4]).match(/(\d+)\s*\/\s*(\d+)/);
  const greenCard = clean(match[5]).match(/(\d+)\s*\/\s*(\d+)/);

  sponsorLookup = {
    ...sponsorLookup,
    found: true,
    resultCount: 1,
    employerName,
    employerPath,
    visaRank: visaRank === '-' ? null : Number(visaRank),

    h1bDeniedOrWithdrawn: h1b ? Number(h1b[1]) : null,
    h1bTotalApplications: h1b ? Number(h1b[2]) : null,

    greenCardDeniedOrWithdrawn: greenCard ? Number(greenCard[1]) : null,
    greenCardTotalApplications: greenCard ? Number(greenCard[2]) : null,
  };
}

return {
  json: {
    ...job,
    sponsor_lookup: sponsorLookup,
  },
};

const lookup = $json.sponsor_lookup ?? {};

let sponsorHistoryStatus;

if (!lookup.found) {
  sponsorHistoryStatus = 'LOOKUP_UNRESOLVED';
} else if (
  Number.isFinite(lookup.h1bTotalApplications) &&
  lookup.h1bTotalApplications > 0
) {
  sponsorHistoryStatus = 'HAS_H1B_HISTORY';
} else if (
  Number.isFinite(lookup.h1bTotalApplications) &&
  lookup.h1bTotalApplications === 0
) {
  sponsorHistoryStatus = 'NO_H1B_HISTORY_FOUND';
} else {
  sponsorHistoryStatus = 'LOOKUP_UNRESOLVED';
}

return {
  json: {
    ...$json,

    sponsor_history: {
      status: sponsorHistoryStatus,
      hasRecentH1BHistory:
        sponsorHistoryStatus === 'HAS_H1B_HISTORY',

      h1bTotalApplications:
        lookup.h1bTotalApplications ?? null,

      h1bDeniedOrWithdrawn:
        lookup.h1bDeniedOrWithdrawn ?? null,

      visaRank:
        lookup.visaRank ?? null,

      matchedEmployer:
        lookup.employerName ?? null,
    },
  },
};

const text = String($json.descriptionText ?? '')
  .replace(/\s+/g, ' ')
  .trim();

const noSponsorshipPatterns = [
  /(?:does not|doesn't|do not|don't|will not|won't|cannot|can't)\s+(?:provide|offer|support)?\s*(?:employment|visa|immigration)?\s*sponsorship/i,

  /no\s+(?:employment|visa|immigration)?\s*sponsorship/i,

  /without\s+(?:current or future\s+)?(?:employment|visa|immigration)?\s*sponsorship/i,

  /not\s+(?:eligible|available)\s+for\s+(?:employment|visa|immigration)?\s*sponsorship/i,

  /must\s+(?:be\s+)?(?:currently\s+)?authorized\s+to\s+work\s+in\s+the\s+(?:u\.?s\.?|united states)\s+without\s+(?:current or future\s+)?sponsorship/i,

  /unable\s+to\s+(?:provide|offer|support)\s+(?:employment|visa|immigration)?\s*sponsorship/i,
];

const sponsorshipAvailablePatterns = [
  /visa\s+sponsorship\s+(?:is\s+)?available/i,
  /sponsorship\s+(?:is\s+)?available/i,
  /we\s+(?:provide|offer|support)\s+(?:employment|visa|immigration)?\s*sponsorship/i,
];

const noMatches = noSponsorshipPatterns
  .filter(pattern => pattern.test(text))
  .map(pattern => pattern.source);

const yesMatches = sponsorshipAvailablePatterns
  .filter(pattern => pattern.test(text))
  .map(pattern => pattern.source);

let status = 'NOT_STATED';

if (noMatches.length > 0 && yesMatches.length > 0) {
  status = 'AMBIGUOUS';
} else if (noMatches.length > 0) {
  status = 'EXPLICIT_NO_SPONSORSHIP';
} else if (yesMatches.length > 0) {
  status = 'EXPLICIT_SPONSORSHIP_AVAILABLE';
}

return {
  json: {
    ...$json,

    job_sponsorship: {
      status,
      explicitRestrictionFound: status === 'EXPLICIT_NO_SPONSORSHIP',
      explicitAvailabilityFound:
        status === 'EXPLICIT_SPONSORSHIP_AVAILABLE',
      matchedNoSponsorshipPatterns: noMatches,
      matchedSponsorshipAvailablePatterns: yesMatches,
    },
  },
};

const descriptionHtml =
  $json.job?.job_information?.description ?? '';

const descriptionText = descriptionHtml
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|li|div|h[1-6]|ul|ol)>/gi, '\n')
  .replace(/<li[^>]*>/gi, '- ')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\n[ \t]+/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return {
  json: {
    ...$json,
    descriptionHtml,
    descriptionText,
  },
};

const jobs = $('Prepare Job Record').all().map(item => item.json);

// Ignore the empty {} generated by Always Output Data
const companyRows = $input.all()
  .map(item => item.json)
  .filter(row => row.id && row.identity_name);

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

const companyByName = new Map();

for (const company of companyRows) {
  companyByName.set(
    normalize(company.identity_name),
    company
  );
}

return jobs.map(job => {
  const companyRecord =
    companyByName.get(normalize(job.company)) ?? null;

  return {
    json: {
      ...job,

      company_record: companyRecord,
      company_id: companyRecord?.id ?? null,
      hasCompanyRecord: Boolean(companyRecord),
    },
  };
});

const jobs = $input.all().map(item => item.json);

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

const companies = new Map();

for (const job of jobs) {
  const identityName = String(job.company ?? '').trim();

  const website = String(
    job.enriched_company_data?.homepage_uri ??
    job.v5_processed_job_data?.company_website ??
    ''
  ).trim();

  if (!identityName) {
    continue;
  }

  const key = `${normalize(identityName)}|${normalize(website)}`;

  if (!companies.has(key)) {
    companies.set(key, {
      identity_name: identityName,
      website: website || null,
    });
  }
}

return Array.from(companies.values()).map(company => ({
  json: company,
}));

// Companies that were just created in Supabase
const createdCompanies = $input.all().map(item => item.json);

// Original jobs that did not previously have a company record
const jobs = $('Attach Company Record')
  .all()
  .map(item => item.json)
  .filter(job => !job.hasCompanyRecord);

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function getJobWebsite(job) {
  return String(
    job.enriched_company_data?.homepage_uri ??
    job.v5_processed_job_data?.company_website ??
    ''
  ).trim();
}

// Build lookup using the same identity + website key
// that we used when deduplicating new companies.
const companyByKey = new Map();

for (const company of createdCompanies) {
  const key =
    `${normalize(company.identity_name)}|${normalize(company.website)}`;

  companyByKey.set(key, company);
}

return jobs.map(job => {
  const website = getJobWebsite(job);

  const key =
    `${normalize(job.company)}|${normalize(website)}`;

  const companyRecord = companyByKey.get(key);

  if (!companyRecord) {
    throw new Error(
      `Could not attach newly created company record for "${job.company}"`
    );
  }

  return {
    json: {
      ...job,

      company_record: companyRecord,
      company_id: companyRecord.id,
      hasCompanyRecord: true,
    },
  };
});

const job = $json;

function extractDomain(url) {
  const value = String(url ?? '').trim();

  const match = value.match(/^https?:\/\/([^/?#]+)/i);

  return match?.[1]?.toLowerCase() ?? null;
}

const applyDomain = extractDomain(
  job.applyUrl ?? job.apply_url
);

return {
  json: {
    ...job,

    job_db_record: {
      id: job.id,
      company_id: job.company_id,

      title: job.title ?? null,
      source: job.source ?? null,
      board_token: job.board_token ?? null,

      apply_url: 
        job.applyUrl ??
        job.apply_url ??
        null,

      apply_domain: applyDomain,

      description_text: job.descriptionText ?? null,
      description_html: job.descriptionHtml ?? null,

      company_identity_basis:
        job.company_identity?.identityBasis ?? null,

      company_identity_confidence:
        job.company_identity?.confidence ?? null,

      company_identity_evidence:
        job.company_identity?.evidence ?? [],

      job_sponsorship_language_status:
        job.job_sponsorship?.status ?? null,

      // Preserve the complete source/context record.
      raw_job: job,
    },
  },
};

const sourceJobs = $('Prepare Job for Supabase')
  .all()
  .map(item => item.json);

// Supabase may return:
// - one {} if nothing matched
// - only the rows that actually matched
// - all rows if all jobs already exist
const lookupResults = $input.all()
  .map(item => item.json)
  .filter(row => row && row.id);

// Build lookup by job ID
const existingJobsById = new Map();

for (const row of lookupResults) {
  existingJobsById.set(row.id, row);
}

return sourceJobs.map(sourceJob => {
  const existingJob =
    existingJobsById.get(sourceJob.id) ?? null;

  return {
    json: {
      ...sourceJob,

      job_record: existingJob,
      hasJobRecord: Boolean(existingJob),
    },
  };
});

const createdJobs = $input.all()
  .map(item => item.json);

const sourceJobs = $('Attach Job Record')
  .all()
  .map(item => item.json)
  .filter(job => !job.hasJobRecord);

const createdById = new Map();

for (const job of createdJobs) {
  createdById.set(job.id, job);
}

return sourceJobs.map(sourceJob => {
  const createdJob =
    createdById.get(sourceJob.id) ?? null;

  if (!createdJob) {
    throw new Error(
      `Could not attach newly created job record for "${sourceJob.id}"`
    );
  }

  return {
    json: {
      ...sourceJob,

      job_record: createdJob,
      hasJobRecord: true,
    },
  };
});

const jobs = $('Prepare Job Record').all().map(item => item.json);

// Remove the empty {} produced by "Always Output Data"
const mappings = $input.all()
  .map(item => item.json)
  .filter(mapping => Object.keys(mapping).length > 0);

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

// Build reusable lookup by Company Identity
const mappingByCompany = new Map();

for (const mapping of mappings) {
  const key = normalize(mapping['Company Identity']);

  if (key) {
    mappingByCompany.set(key, mapping);
  }
}

return jobs.map(job => {
  const mapping =
    mappingByCompany.get(normalize(job.company)) ?? null;

  return {
    json: {
      ...job,

      sponsor_entity_mapping: mapping,

      hasSponsorEntityMapping: Boolean(
        mapping &&
        mapping['Mapping Status'] === 'Verified' &&
        mapping['Verified Sponsor Entity Name']
      ),
    },
  };
});

const sourceJobs = [
  ...$('Attach Job Record')
    .all()
    .map(item => item.json)
    .filter(job => job.hasJobRecord),

  ...$('Attach Created Job Record')
    .all()
    .map(item => item.json),
];

// Remove duplicate jobs in case one of the branches contributes
// something already represented above.
const jobsById = new Map();

for (const job of sourceJobs) {
  jobsById.set(job.id, job);
}

const jobs = Array.from(jobsById.values());

// Ignore {} produced by Always Output Data
const mappingRows = $input.all()
  .map(item => item.json)
  .filter(row => row && row.id && row.company_id);

// A company may eventually have more than one mapping.
const mappingsByCompanyId = new Map();

for (const mapping of mappingRows) {
  const existing =
    mappingsByCompanyId.get(mapping.company_id) ?? [];

  existing.push(mapping);

  mappingsByCompanyId.set(
    mapping.company_id,
    existing
  );
}

return jobs.map(job => {
  const mappings =
    mappingsByCompanyId.get(job.company_id) ?? [];

  return {
    json: {
      ...job,

      sponsor_entity_mappings: mappings,

      sponsor_entity_mapping_count:
        mappings.length,

      sponsor_entity_mapping:
        mappings.length === 1
          ? mappings[0]
          : null,

      hasUniqueSponsorEntityMapping:
        mappings.length === 1,
    },
  };
});
